// CRMServiceHandler is an implementation of the crm.v1.CRMService service.
type CRMServiceHandler interface {
	CreateAccount(context.Context, *connect.Request[v1.CreateAccountRequest]) (*connect.Response[v1.CreateAccountResponse], error)
	GetAccount(context.Context, *connect.Request[v1.GetAccountRequest]) (*connect.Response[v1.GetAccountResponse], error)
	ListAccounts(context.Context, *connect.Request[v1.ListAccountsRequest]) (*connect.Response[v1.ListAccountsResponse], error)
	UpdateAccount(context.Context, *connect.Request[v1.UpdateAccountRequest]) (*connect.Response[v1.UpdateAccountResponse], error)
	DeleteAccount(context.Context, *connect.Request[v1.DeleteAccountRequest]) (*connect.Response[v1.DeleteAccountResponse], error)
	CreateContact(context.Context, *connect.Request[v1.CreateContactRequest]) (*connect.Response[v1.CreateContactResponse], error)
	GetContact(context.Context, *connect.Request[v1.GetContactRequest]) (*connect.Response[v1.GetContactResponse], error)
	ListContacts(context.Context, *connect.Request[v1.ListContactsRequest]) (*connect.Response[v1.ListContactsResponse], error)
	UpdateContact(context.Context, *connect.Request[v1.UpdateContactRequest]) (*connect.Response[v1.UpdateContactResponse], error)
	DeleteContact(context.Context, *connect.Request[v1.DeleteContactRequest]) (*connect.Response[v1.DeleteContactResponse], error)
	CreateLead(context.Context, *connect.Request[v1.CreateLeadRequest]) (*connect.Response[v1.CreateLeadResponse], error)
	GetLead(context.Context, *connect.Request[v1.GetLeadRequest]) (*connect.Response[v1.GetLeadResponse], error)
	ListLeads(context.Context, *connect.Request[v1.ListLeadsRequest]) (*connect.Response[v1.ListLeadsResponse], error)
	UpdateLead(context.Context, *connect.Request[v1.UpdateLeadRequest]) (*connect.Response[v1.UpdateLeadResponse], error)
	DeleteLead(context.Context, *connect.Request[v1.DeleteLeadRequest]) (*connect.Response[v1.DeleteLeadResponse], error)
	// ConvertLead is the load-bearing B1 operation (docs/customer-os/PLAN.md):
	// in one transaction it creates (or reuses, if the lead's email already
	// names one) a Contact, attaches it to an Account (existing match by email
	// domain, or a new one), optionally creates an Opportunity, and marks the
	// lead converted with the linked ids. Retrying with the same lead_id is a
	// no-op that returns the ids the first successful call produced.
	ConvertLead(context.Context, *connect.Request[v1.ConvertLeadRequest]) (*connect.Response[v1.ConvertLeadResponse], error)
	CreateOpportunity(context.Context, *connect.Request[v1.CreateOpportunityRequest]) (*connect.Response[v1.CreateOpportunityResponse], error)
	GetOpportunity(context.Context, *connect.Request[v1.GetOpportunityRequest]) (*connect.Response[v1.GetOpportunityResponse], error)
	ListOpportunities(context.Context, *connect.Request[v1.ListOpportunitiesRequest]) (*connect.Response[v1.ListOpportunitiesResponse], error)
	UpdateOpportunity(context.Context, *connect.Request[v1.UpdateOpportunityRequest]) (*connect.Response[v1.UpdateOpportunityResponse], error)
	// MoveOpportunityToPipeline is deliberately narrower than UpdateOpportunity:
	// cross-pipeline moves require an explicit destination pipeline and open
	// stage, while preserving the deal's other fields and its audit history.
	MoveOpportunityToPipeline(context.Context, *connect.Request[v1.MoveOpportunityToPipelineRequest]) (*connect.Response[v1.MoveOpportunityToPipelineResponse], error)
	DeleteOpportunity(context.Context, *connect.Request[v1.DeleteOpportunityRequest]) (*connect.Response[v1.DeleteOpportunityResponse], error)
	// Returns the append-only history for an opportunity. This is intentionally
	// separate from the mutable opportunity response so history remains useful
	// for audit and reporting clients.
	ListOpportunityStageHistory(context.Context, *connect.Request[v1.ListOpportunityStageHistoryRequest]) (*connect.Response[v1.ListOpportunityStageHistoryResponse], error)
	// Pipeline configuration is organization administration data. These RPCs
	// manage definitions only; the later opportunity migration will bind each
	// deal to pipeline_id/stage_id without rewriting historical stage text.
	CreatePipeline(context.Context, *connect.Request[v1.CreatePipelineRequest]) (*connect.Response[v1.CreatePipelineResponse], error)
	GetPipeline(context.Context, *connect.Request[v1.GetPipelineRequest]) (*connect.Response[v1.GetPipelineResponse], error)
	ListPipelines(context.Context, *connect.Request[v1.ListPipelinesRequest]) (*connect.Response[v1.ListPipelinesResponse], error)
	UpdatePipeline(context.Context, *connect.Request[v1.UpdatePipelineRequest]) (*connect.Response[v1.UpdatePipelineResponse], error)
	CreatePipelineStage(context.Context, *connect.Request[v1.CreatePipelineStageRequest]) (*connect.Response[v1.CreatePipelineStageResponse], error)
	ListPipelineStages(context.Context, *connect.Request[v1.ListPipelineStagesRequest]) (*connect.Response[v1.ListPipelineStagesResponse], error)
	UpdatePipelineStage(context.Context, *connect.Request[v1.UpdatePipelineStageRequest]) (*connect.Response[v1.UpdatePipelineStageResponse], error)
	CreateActivity(context.Context, *connect.Request[v1.CreateActivityRequest]) (*connect.Response[v1.CreateActivityResponse], error)
	GetActivity(context.Context, *connect.Request[v1.GetActivityRequest]) (*connect.Response[v1.GetActivityResponse], error)
	ListActivities(context.Context, *connect.Request[v1.ListActivitiesRequest]) (*connect.Response[v1.ListActivitiesResponse], error)
	UpdateActivity(context.Context, *connect.Request[v1.UpdateActivityRequest]) (*connect.Response[v1.UpdateActivityResponse], error)
	DeleteActivity(context.Context, *connect.Request[v1.DeleteActivityRequest]) (*connect.Response[v1.DeleteActivityResponse], error)
	// ListActivitiesForSubject is the B5 timeline query
	// (docs/customer-os/PLAN.md): every Activity attached to one polymorphic
	// subject (subject_type + subject_id), newest first by occurred_at.
	ListActivitiesForSubject(context.Context, *connect.Request[v1.ListActivitiesForSubjectRequest]) (*connect.Response[v1.ListActivitiesForSubjectResponse], error)
	// Tasks and Notes are first-class entities, not Activity kinds.
	//
	// An Activity records what happened and is immutable once logged. A Task
	// records what should happen: it has a lifecycle, an assignee and a due
	// date, and it is edited repeatedly until it is done. A Note is authored
	// prose that gets corrected. Expressing either as an Activity would mean
	// making Activity mutable — destroying the property that makes it useful
	// for audit — or storing tasks that can never be completed.
	CreateTask(context.Context, *connect.Request[v1.CreateTaskRequest]) (*connect.Response[v1.CreateTaskResponse], error)
	GetTask(context.Context, *connect.Request[v1.GetTaskRequest]) (*connect.Response[v1.GetTaskResponse], error)
	ListTasks(context.Context, *connect.Request[v1.ListTasksRequest]) (*connect.Response[v1.ListTasksResponse], error)
	UpdateTask(context.Context, *connect.Request[v1.UpdateTaskRequest]) (*connect.Response[v1.UpdateTaskResponse], error)
	DeleteTask(context.Context, *connect.Request[v1.DeleteTaskRequest]) (*connect.Response[v1.DeleteTaskResponse], error)
	// CompleteTask and ReopenTask are separate from UpdateTask on purpose.
	// Ticking a checkbox should not require sending the whole record back:
	// that is a read-modify-write, and under optimistic concurrency it either
	// fails against a concurrent edit or silently clobbers one. Both are
	// idempotent — completing a completed task returns it unchanged.
	CompleteTask(context.Context, *connect.Request[v1.CompleteTaskRequest]) (*connect.Response[v1.CompleteTaskResponse], error)
	ReopenTask(context.Context, *connect.Request[v1.ReopenTaskRequest]) (*connect.Response[v1.ReopenTaskResponse], error)
	CreateNote(context.Context, *connect.Request[v1.CreateNoteRequest]) (*connect.Response[v1.CreateNoteResponse], error)
	GetNote(context.Context, *connect.Request[v1.GetNoteRequest]) (*connect.Response[v1.GetNoteResponse], error)
	ListNotes(context.Context, *connect.Request[v1.ListNotesRequest]) (*connect.Response[v1.ListNotesResponse], error)
	UpdateNote(context.Context, *connect.Request[v1.UpdateNoteRequest]) (*connect.Response[v1.UpdateNoteResponse], error)
	DeleteNote(context.Context, *connect.Request[v1.DeleteNoteRequest]) (*connect.Response[v1.DeleteNoteResponse], error)
	// Custom-field definitions are tenant administration data. Values travel on
	// the shipped record messages above, but a definition is the authority for
	// their type, requiredness, picklist options, and lookup target.
	CreateCustomFieldDefinition(context.Context, *connect.Request[v1.CreateCustomFieldDefinitionRequest]) (*connect.Response[v1.CreateCustomFieldDefinitionResponse], error)
	GetCustomFieldDefinition(context.Context, *connect.Request[v1.GetCustomFieldDefinitionRequest]) (*connect.Response[v1.GetCustomFieldDefinitionResponse], error)
	ListCustomFieldDefinitions(context.Context, *connect.Request[v1.ListCustomFieldDefinitionsRequest]) (*connect.Response[v1.ListCustomFieldDefinitionsResponse], error)
	UpdateCustomFieldDefinition(context.Context, *connect.Request[v1.UpdateCustomFieldDefinitionRequest]) (*connect.Response[v1.UpdateCustomFieldDefinitionResponse], error)
	ArchiveCustomFieldDefinition(context.Context, *connect.Request[v1.ArchiveCustomFieldDefinitionRequest]) (*connect.Response[v1.ArchiveCustomFieldDefinitionResponse], error)
	CreateCustomObjectDefinition(context.Context, *connect.Request[v1.CreateCustomObjectDefinitionRequest]) (*connect.Response[v1.CreateCustomObjectDefinitionResponse], error)
	GetCustomObjectDefinition(context.Context, *connect.Request[v1.GetCustomObjectDefinitionRequest]) (*connect.Response[v1.GetCustomObjectDefinitionResponse], error)
	ListCustomObjectDefinitions(context.Context, *connect.Request[v1.ListCustomObjectDefinitionsRequest]) (*connect.Response[v1.ListCustomObjectDefinitionsResponse], error)
	ArchiveCustomObjectDefinition(context.Context, *connect.Request[v1.ArchiveCustomObjectDefinitionRequest]) (*connect.Response[v1.ArchiveCustomObjectDefinitionResponse], error)
	CreateCustomRecord(context.Context, *connect.Request[v1.CreateCustomRecordRequest]) (*connect.Response[v1.CreateCustomRecordResponse], error)
	GetCustomRecord(context.Context, *connect.Request[v1.GetCustomRecordRequest]) (*connect.Response[v1.GetCustomRecordResponse], error)
	ListCustomRecords(context.Context, *connect.Request[v1.ListCustomRecordsRequest]) (*connect.Response[v1.ListCustomRecordsResponse], error)
	UpdateCustomRecord(context.Context, *connect.Request[v1.UpdateCustomRecordRequest]) (*connect.Response[v1.UpdateCustomRecordResponse], error)
	DeleteCustomRecord(context.Context, *connect.Request[v1.DeleteCustomRecordRequest]) (*connect.Response[v1.DeleteCustomRecordResponse], error)
	GetSummary(context.Context, *connect.Request[v1.GetSummaryRequest]) (*connect.Response[v1.GetSummaryResponse], error)
	// SearchRecords is the bounded, tenant-scoped quick-search surface used by
	// the command palette. It searches the primary identifying fields of the
	// core record types in the database; clients must not implement search by
	// downloading arbitrary list pages and filtering them locally.
	SearchRecords(context.Context, *connect.Request[v1.SearchRecordsRequest]) (*connect.Response[v1.SearchRecordsResponse], error)
	// The Google connection (docs/GOOGLE_INTEGRATION.md).
	//
	// Every RPC here acts on the *calling principal's own* connection. None of
	// them takes an owner: Gmail and Calendar consent belongs to the person who
	// granted it, so letting a request name whose mailbox to disconnect — or
	// whose authorization to start — would be an authorization bug no scope
	// could fix. ListGoogleConnections is the one administrative view, and it
	// returns status only.
	//
	// No response here ever carries a token, a refresh token, a PKCE verifier,
	// or the OAuth client secret. The credential stays sealed server-side; see
	// internal/integration/google.
	StartGoogleConnection(context.Context, *connect.Request[v1.StartGoogleConnectionRequest]) (*connect.Response[v1.StartGoogleConnectionResponse], error)
	GetGoogleConnection(context.Context, *connect.Request[v1.GetGoogleConnectionRequest]) (*connect.Response[v1.GetGoogleConnectionResponse], error)
	ListGoogleConnections(context.Context, *connect.Request[v1.ListGoogleConnectionsRequest]) (*connect.Response[v1.ListGoogleConnectionsResponse], error)
	DisconnectGoogleConnection(context.Context, *connect.Request[v1.DisconnectGoogleConnectionRequest]) (*connect.Response[v1.DisconnectGoogleConnectionResponse], error)
	// SyncGoogleMailbox runs one Gmail synchronisation pass for the calling
	// user's own mailbox, now, rather than waiting for the background poller.
	// It is bounded: one pass examines a fixed number of messages and stores a
	// cursor, so a large mailbox needs several and the caller can simply ask
	// again.
	SyncGoogleMailbox(context.Context, *connect.Request[v1.SyncGoogleMailboxRequest]) (*connect.Response[v1.SyncGoogleMailboxResponse], error)
	// SyncGoogleCalendar is SyncGoogleMailbox's twin for the calling user's own
	// calendar, and is bounded the same way.
	SyncGoogleCalendar(context.Context, *connect.Request[v1.SyncGoogleCalendarRequest]) (*connect.Response[v1.SyncGoogleCalendarResponse], error)
	// Data-subject requests against synchronised communication content
	// (docs/GOOGLE_INTEGRATION.md).
	//
	// These are administrative rather than personal: unlike the sync RPCs they
	// name a record or an address, because the person exercising a right is
	// usually not the person holding the CRM login. They carry their own scope
	// for that reason.
	EraseSyncedContentForContact(context.Context, *connect.Request[v1.EraseSyncedContentForContactRequest]) (*connect.Response[v1.EraseSyncedContentResponse], error)
	ListSyncSuppressions(context.Context, *connect.Request[v1.ListSyncSuppressionsRequest]) (*connect.Response[v1.ListSyncSuppressionsResponse], error)
	SuppressSyncAddress(context.Context, *connect.Request[v1.SuppressSyncAddressRequest]) (*connect.Response[v1.SuppressSyncAddressResponse], error)
	ReleaseSyncAddress(context.Context, *connect.Request[v1.ReleaseSyncAddressRequest]) (*connect.Response[v1.ReleaseSyncAddressResponse], error)
	// Workflow automation (docs/WORKFLOW_AUTOMATION.md).
	//
	// A rule is authored as a draft, published as an immutable version, and
	// then activated. Editing never mutates what is running: PublishWorkflow-
	// RuleVersion writes a new version, and the rule keeps executing the one it
	// points at until somebody activates the new one. That is what makes an
	// execution's ledger row meaningful — it names the exact text of the rule
	// that ran, months later, after the rule has been edited four times.
	//
	// DescribeWorkflowCatalog exists so the editor offers exactly what the
	// server accepts. Triggers, comparable fields, operators and action types
	// are allowlists; a UI that guessed at them would let an author compose a
	// rule that cannot be saved, or worse, one that saves and never matches.
	DescribeWorkflowCatalog(context.Context, *connect.Request[v1.DescribeWorkflowCatalogRequest]) (*connect.Response[v1.DescribeWorkflowCatalogResponse], error)
	CreateWorkflowRule(context.Context, *connect.Request[v1.CreateWorkflowRuleRequest]) (*connect.Response[v1.CreateWorkflowRuleResponse], error)
	GetWorkflowRule(context.Context, *connect.Request[v1.GetWorkflowRuleRequest]) (*connect.Response[v1.GetWorkflowRuleResponse], error)
	ListWorkflowRules(context.Context, *connect.Request[v1.ListWorkflowRulesRequest]) (*connect.Response[v1.ListWorkflowRulesResponse], error)
	UpdateWorkflowRule(context.Context, *connect.Request[v1.UpdateWorkflowRuleRequest]) (*connect.Response[v1.UpdateWorkflowRuleResponse], error)
	PublishWorkflowRuleVersion(context.Context, *connect.Request[v1.PublishWorkflowRuleVersionRequest]) (*connect.Response[v1.PublishWorkflowRuleVersionResponse], error)
	ListWorkflowRuleVersions(context.Context, *connect.Request[v1.ListWorkflowRuleVersionsRequest]) (*connect.Response[v1.ListWorkflowRuleVersionsResponse], error)
	SetWorkflowRuleStatus(context.Context, *connect.Request[v1.SetWorkflowRuleStatusRequest]) (*connect.Response[v1.SetWorkflowRuleStatusResponse], error)
	// ListWorkflowExecutions is the answer to "why didn't my rule fire": every
	// event the rule was considered for, including the ones whose conditions
	// did not hold, and the bounded reason for each failure.
	ListWorkflowExecutions(context.Context, *connect.Request[v1.ListWorkflowExecutionsRequest]) (*connect.Response[v1.ListWorkflowExecutionsResponse], error)
	// In-app notifications.
	//
	// Both RPCs act on the calling principal's own notifications and take no
	// recipient, for the same reason the Google RPCs take no owner: letting a
	// request name whose inbox to read would be an authorization bug no scope
	// could fix.
	ListNotifications(context.Context, *connect.Request[v1.ListNotificationsRequest]) (*connect.Response[v1.ListNotificationsResponse], error)
	MarkNotificationRead(context.Context, *connect.Request[v1.MarkNotificationReadRequest]) (*connect.Response[v1.MarkNotificationReadResponse], error)
	// Tags (M4 — data productivity). A tag is a tenant-authored label; an
	// assignment attaches one to one record of an allowlisted type (account,
	// contact, lead, opportunity, task). AssignTag and RemoveTag are
	// idempotent, so a bulk "add tag" action can retry a partial batch safely.
	CreateTag(context.Context, *connect.Request[v1.CreateTagRequest]) (*connect.Response[v1.CreateTagResponse], error)
	ListTags(context.Context, *connect.Request[v1.ListTagsRequest]) (*connect.Response[v1.ListTagsResponse], error)
	UpdateTag(context.Context, *connect.Request[v1.UpdateTagRequest]) (*connect.Response[v1.UpdateTagResponse], error)
	DeleteTag(context.Context, *connect.Request[v1.DeleteTagRequest]) (*connect.Response[v1.DeleteTagResponse], error)
	AssignTag(context.Context, *connect.Request[v1.AssignTagRequest]) (*connect.Response[v1.AssignTagResponse], error)
	RemoveTag(context.Context, *connect.Request[v1.RemoveTagRequest]) (*connect.Response[v1.RemoveTagResponse], error)
	ListTagsForRecord(context.Context, *connect.Request[v1.ListTagsForRecordRequest]) (*connect.Response[v1.ListTagsForRecordResponse], error)
	// ListTaggedRecords is the filter surface a list page uses to answer "show
	// me every record tagged X" until per-entity filters grow a tag field of
	// their own.
	ListTaggedRecords(context.Context, *connect.Request[v1.ListTaggedRecordsRequest]) (*connect.Response[v1.ListTaggedRecordsResponse], error)
	// Bulk operations (M4 — data productivity).
	//
	// Every bulk RPC is bounded (see maxBulkBatch in internal/api) and reports
	// one BulkItemResult per requested id rather than succeeding or failing as
	// a unit: a batch is not a transaction, and telling a caller "12 of 40
	// succeeded, here are the 28 that did not and why" is the honest answer
	// when the underlying per-record operations already have their own
	// semantics (idempotent assign/remove, optimistic-concurrency updates).
	// Each item is authorized exactly as its single-record RPC would be —
	// scope-gated by procedure, then existence-checked per id inside the
	// caller's own tenant — so a foreign or nonexistent id fails only that
	// item, the same NotFound a direct call would produce.
	BulkAssignTag(context.Context, *connect.Request[v1.BulkAssignTagRequest]) (*connect.Response[v1.BulkAssignTagResponse], error)
	BulkRemoveTag(context.Context, *connect.Request[v1.BulkRemoveTagRequest]) (*connect.Response[v1.BulkRemoveTagResponse], error)
	BulkCompleteTasks(context.Context, *connect.Request[v1.BulkCompleteTasksRequest]) (*connect.Response[v1.BulkCompleteTasksResponse], error)
	BulkReopenTasks(context.Context, *connect.Request[v1.BulkReopenTasksRequest]) (*connect.Response[v1.BulkReopenTasksResponse], error)
	BulkReassignTaskAssignee(context.Context, *connect.Request[v1.BulkReassignTaskAssigneeRequest]) (*connect.Response[v1.BulkReassignTaskAssigneeResponse], error)
	// BulkReassignAccountOwner and BulkReassignLeadOwner are separate RPCs
	// rather than one parameterized by object_type, so each can carry its own
	// static write scope (crm:account:write / crm:lead:write) the way every
	// other entity-specific RPC does, instead of a scope check that depends on
	// a request field the interceptor's static policy cannot see.
	BulkReassignAccountOwner(context.Context, *connect.Request[v1.BulkReassignAccountOwnerRequest]) (*connect.Response[v1.BulkReassignAccountOwnerResponse], error)
	BulkReassignLeadOwner(context.Context, *connect.Request[v1.BulkReassignLeadOwnerRequest]) (*connect.Response[v1.BulkReassignLeadOwnerResponse], error)
	// Saved views (M4 — data productivity). Private to the caller by
	// construction — see internal/domain/saved_views.go's doc comment for why
	// there is no sharing yet — so every RPC here reads only the caller's own
	// views, the same way notifications do.
	CreateSavedView(context.Context, *connect.Request[v1.CreateSavedViewRequest]) (*connect.Response[v1.CreateSavedViewResponse], error)
	ListSavedViews(context.Context, *connect.Request[v1.ListSavedViewsRequest]) (*connect.Response[v1.ListSavedViewsResponse], error)
	UpdateSavedView(context.Context, *connect.Request[v1.UpdateSavedViewRequest]) (*connect.Response[v1.UpdateSavedViewResponse], error)
	DeleteSavedView(context.Context, *connect.Request[v1.DeleteSavedViewRequest]) (*connect.Response[v1.DeleteSavedViewResponse], error)
	// Account deduplication and merge (M4 — data productivity). There is no
	// undo — see internal/domain/merge_accounts.go's package doc comment for
	// why — so a client must confirm with the caller before sending this.
	MergeAccounts(context.Context, *connect.Request[v1.MergeAccountsRequest]) (*connect.Response[v1.MergeAccountsResponse], error)
	// ListAccountMerges is the immutable audit trail: every merge one account
	// was ever part of, as the kept id or the retired one.
	ListAccountMerges(context.Context, *connect.Request[v1.ListAccountMergesRequest]) (*connect.Response[v1.ListAccountMergesResponse], error)
	// CSV import and export, accounts only in v1 (M4 — data productivity).
	// See docs/CSV_IMPORT_EXPORT.md for the full product decision record:
	// size bounds, field mapping, duplicate policy, and — importantly —
	// that both run synchronously inside the RPC call rather than as a
	// true background job, and that a committed import has no rollback.
	//
	// CreateImportJob is the dry run: it validates and stores the upload,
	// returning per-row errors, without creating any Account.
	// CommitImportJob is what actually creates them, and is idempotent —
	// calling it again on an already-completed job returns the stored
	// result rather than re-running it.
	CreateImportJob(context.Context, *connect.Request[v1.CreateImportJobRequest]) (*connect.Response[v1.CreateImportJobResponse], error)
	GetImportJob(context.Context, *connect.Request[v1.GetImportJobRequest]) (*connect.Response[v1.GetImportJobResponse], error)
	ListImportJobs(context.Context, *connect.Request[v1.ListImportJobsRequest]) (*connect.Response[v1.ListImportJobsResponse], error)
	CommitImportJob(context.Context, *connect.Request[v1.CommitImportJobRequest]) (*connect.Response[v1.CommitImportJobResponse], error)
	// ExportAccounts generates and returns CSV for the caller's own tenant,
	// bounded at 500 rows, inline in the response — there is no object
	// storage to hand back a download link from (docs/CSV_IMPORT_EXPORT.md).
	ExportAccounts(context.Context, *connect.Request[v1.ExportAccountsRequest]) (*connect.Response[v1.ExportAccountsResponse], error)
	// ListExportJobs is the audit trail of who exported, when, and how many
	// rows — the export content itself is never persisted.
	ListExportJobs(context.Context, *connect.Request[v1.ListExportJobsRequest]) (*connect.Response[v1.ListExportJobsResponse], error)
	// GetDashboardReport is the bounded, tenant-scoped reporting surface
	// (M4 — data productivity): one page of pipeline/stage summary per
	// pipeline, a task status summary, the lead conversion funnel, and the
	// default-weighted pipeline forecast. See internal/domain/reporting.go
	// for the canonical metric semantics (currency, time zone, pipeline
	// status, and forecast) this report follows.
	GetDashboardReport(context.Context, *connect.Request[v1.GetDashboardReportRequest]) (*connect.Response[v1.GetDashboardReportResponse], error)
	// Messaging channels and consent (task_crm.md §2).
	//
	// ListContactChannels is the read every messaging UI makes. It returns one
	// entry per channel a contact could be reached on, each already carrying
	// the answer to "may we use this" — because that answer is
	// domain.MayMessage's, and a browser that fetched the address and the
	// consent rows separately would be re-deciding it client-side, which is
	// exactly the check that must not be reimplementable.
	//
	// A channel whose number has no country code comes back unreachable with a
	// reason rather than absent: a local number cannot be keyed unambiguously
	// in the consent ledger, and inferring the country code would produce a
	// different person's number. See internal/domain/messaging.go.
	ListContactChannels(context.Context, *connect.Request[v1.ListContactChannelsRequest]) (*connect.Response[v1.ListContactChannelsResponse], error)
	// RecordMessagingConsent appends one decision. There is no update and no
	// delete: withdrawing is a new row saying so, which is what lets the ledger
	// answer when a decision was made and on what evidence.
	RecordMessagingConsent(context.Context, *connect.Request[v1.RecordMessagingConsentRequest]) (*connect.Response[v1.RecordMessagingConsentResponse], error)
	// ListMessagingConsent is that history for one address on one channel,
	// newest first — the read a compliance or support question needs.
	ListMessagingConsent(context.Context, *connect.Request[v1.ListMessagingConsentRequest]) (*connect.Response[v1.ListMessagingConsentResponse], error)
	// Message templates (task_crm.md §5). Reusable wording per channel, shared
	// across the tenant the way tags are rather than owned per user.
	//
	// A body may carry {{placeholders}} from a fixed allowlist, refused at save
	// time if unknown — a template that shipped "{{contact.phone}}" verbatim is
	// a mistake the author hears about from the recipient, if at all. Nothing
	// expands one on the server: the browser substitutes from the record it is
	// already showing, for somebody already looking at it, which is why this
	// needs none of the field-visibility model that still blocks templated
	// workflow action text.
	CreateMessageTemplate(context.Context, *connect.Request[v1.CreateMessageTemplateRequest]) (*connect.Response[v1.CreateMessageTemplateResponse], error)
	ListMessageTemplates(context.Context, *connect.Request[v1.ListMessageTemplatesRequest]) (*connect.Response[v1.ListMessageTemplatesResponse], error)
	UpdateMessageTemplate(context.Context, *connect.Request[v1.UpdateMessageTemplateRequest]) (*connect.Response[v1.UpdateMessageTemplateResponse], error)
	DeleteMessageTemplate(context.Context, *connect.Request[v1.DeleteMessageTemplateRequest]) (*connect.Response[v1.DeleteMessageTemplateResponse], error)
	// DescribeMessageTemplateCatalog reports the channels a template may be
	// written for and the merge fields it may use, so the editor offers exactly
	// what the server accepts rather than holding its own copy of the list.
	DescribeMessageTemplateCatalog(context.Context, *connect.Request[v1.DescribeMessageTemplateCatalogRequest]) (*connect.Response[v1.DescribeMessageTemplateCatalogResponse], error)
	// Inbound lead capture (task_crm.md §1, docs/LEAD_CAPTURE.md).
	//
	// These administer the endpoints; the deliveries themselves arrive on an
	// unauthenticated HTTP route, not through this service.
	//
	// Creating an endpoint is tenant-wide authority to create records — anybody
	// holding the URL and the secret can make leads — so it sits behind its own
	// crm:capture scope pair rather than crm:lead:write. A member who may
	// create a lead by hand still may not mint a URL that lets the internet do
	// it.
	//
	// The signing secret is returned exactly once, by Create and by Rotate. It
	// is stored sealed and there is no RPC that reads one back: a secret an API
	// can return is a secret every future bug can leak.
	CreateLeadCaptureEndpoint(context.Context, *connect.Request[v1.CreateLeadCaptureEndpointRequest]) (*connect.Response[v1.CreateLeadCaptureEndpointResponse], error)
	ListLeadCaptureEndpoints(context.Context, *connect.Request[v1.ListLeadCaptureEndpointsRequest]) (*connect.Response[v1.ListLeadCaptureEndpointsResponse], error)
	UpdateLeadCaptureEndpoint(context.Context, *connect.Request[v1.UpdateLeadCaptureEndpointRequest]) (*connect.Response[v1.UpdateLeadCaptureEndpointResponse], error)
	RotateLeadCaptureSecret(context.Context, *connect.Request[v1.RotateLeadCaptureSecretRequest]) (*connect.Response[v1.RotateLeadCaptureSecretResponse], error)
	// ListLeadCaptureDeliveries is this feature's own debugger: every delivery
	// with its outcome, including the rejected ones. Without it every failure
	// is a support call.
	ListLeadCaptureDeliveries(context.Context, *connect.Request[v1.ListLeadCaptureDeliveriesRequest]) (*connect.Response[v1.ListLeadCaptureDeliveriesResponse], error)
	// Messages an automation has drafted (task_crm.md §6).
	//
	// Drafts, never sends. Nothing in this service delivers a message —
	// provider-sent messaging is §4 and waits on a provider contract — so a
	// rule decides who to contact, checks that contacting them is permitted,
	// and writes the wording; a rep sends it in one tap through the same
	// click-to-chat links they use by hand.
	//
	// MarkOutboundMessageSent records that a human sent it. It is the honest
	// verb: the service did not send anything and must not claim to.
	ListOutboundMessages(context.Context, *connect.Request[v1.ListOutboundMessagesRequest]) (*connect.Response[v1.ListOutboundMessagesResponse], error)
	MarkOutboundMessageSent(context.Context, *connect.Request[v1.MarkOutboundMessageSentRequest]) (*connect.Response[v1.MarkOutboundMessageSentResponse], error)
	DiscardOutboundMessage(context.Context, *connect.Request[v1.DiscardOutboundMessageRequest]) (*connect.Response[v1.DiscardOutboundMessageResponse], error)
}

